"""Offline orbitable pitched-roof hypothesis with source plan and gable evidence."""
import argparse,base64,json
from pathlib import Path
import numpy as np
from PIL import Image
import pymupdf
from voxel_mapper.generation_cycles import file_hash


def render(gable,profile,preview,components,views,output):
    gable,profile,preview,components,views,output=map(Path,(gable,profile,preview,components,views,output))
    evidence=json.loads((gable/'gable-roof-review.json').read_text());contract=evidence['contract']
    for path,pin in [(profile/'facade-profile.json',contract['source_profile_sha256']),(preview/'facade-preview.json',contract['source_preview_sha256']),
        (components/'component-report.json',contract['component_report_sha256']),(views/'view-report.json',contract['view_report_sha256'])]:
        if file_hash(path)!=pin:raise ValueError('Gable roof source report changed')
    report=json.loads((views/'view-report.json').read_text())
    for name,pin in report['output_sha256'].items():
        if file_hash(views/name)!=pin:raise ValueError('Original gable source changed')
    source=json.loads((views/'view-candidates.json').read_text());lookup={v['id']:v for p in source['pages'] for v in p['views']}
    previous=json.loads((profile/'facade-profile.json').read_text())
    payload={'evidence':evidence,'review_sha256':file_hash(gable/'gable-roof-review.json'),'views':{},'profiles':{p['id']:p for p in previous['profiles']}}
    needed={v['view_id'] for v in evidence['gable_views']}|{v['source_view_id'] for v in evidence['plan_reviews']}|{m['source_long_view_id'] for m in evidence['models']}
    for key in needed:
        v=lookup[key];receipt=json.loads((views/v['render']['receipt']).read_text());image_path=views/v['render']['png']
        with Image.open(image_path) as image:gray=np.asarray(image.convert('L'))
        yy,xx=np.nonzero(gray<245)
        crop=[max(0,int(xx.min())-15),max(0,int(yy.min())-15),min(gray.shape[1],int(xx.max())+16),min(gray.shape[0],int(yy.max())+16)] if len(xx) else [0,0,gray.shape[1],gray.shape[0]]
        payload['views'][key]={'caption':v['caption_text'],'size':receipt['size_pixels'],'display_box':crop,
            'native_to_pixel_matrix':list(~pymupdf.Matrix(receipt['pixel_edge_to_pdf_native_matrix'])),
            'source_png_sha256':v['render']['png_sha256'],'png':'data:image/png;base64,'+base64.b64encode(image_path.read_bytes()).decode()}
    html=r'''<!doctype html><html lang="en"><meta charset="utf-8"><title>Automatic pitched roof source review</title>
<style>body{font:16px system-ui;margin:24px;background:#f3f6f9;color:#18232f}h1{margin-bottom:8px}p{max-width:1250px;line-height:1.5}.notice{background:#fff3d6;padding:14px;border-left:4px solid #b57500}.controls{display:flex;flex-wrap:wrap;align-items:center;gap:18px;margin:16px 0}select,button{font:inherit;padding:7px}.panels{display:grid;grid-template-columns:1fr 1fr;gap:20px}article{background:white;border:1px solid #ccd5e0;padding:15px}h2{font-size:19px}svg{width:100%;height:360px}.small{font-size:14px;color:#495b6c}table{width:100%;border-collapse:collapse;margin:16px 0}td,th{padding:8px;text-align:left;border-bottom:1px solid #ccd5e0}.agree{color:#116552}@media(max-width:850px){.panels{grid-template-columns:1fr}}</style>
<h1>Main roof · automatic pitched geometry</h1><p id="summary"></p><p class="notice">Conditional unplaced roof model. Three original roof-plan lines supply depth and ridge position; the long elevation supplies length and heights. Separate end-elevation slopes check the model without refitting. Continuous roof planes are assumed. Source mask gaps remain in the preceding profile; their physical roles are unresolved. This review contains no walls, fascia, material assignment or park placement.</p>
<div class="controls"><label>Source height witness <select id="model"></select></label><label>Orbit <input id="yaw" type="range" min="-180" max="180" value="30"></label><label>Tilt <input id="tilt" type="range" min="10" max="65" value="45"></label><button id="obj">Download conditional roof OBJ</button></div><p id="measurements"></p>
<div class="panels"><article><h2>Provisional 3D roof · nominal metres</h2><svg id="roof" viewBox="0 0 800 400" role="img" aria-label="Orbitable pitched roof model"></svg><p class="small">Six source-derived vertices and four triangles. The two source height witnesses yield the same geometry. The slight measured transverse offset is retained; symmetry is not forced. Roof identity, construction state, physical scale and registration remain unverified.</p></article><article><h2>Original roof plan · three candidate lines</h2><svg id="plan" role="img" aria-label="Original roof plan with eave ridge eave candidates"></svg><p class="small">Blue: two original outer lines. Gold: original middle line. All endpoints remain unchanged. Their eave/ridge roles are hypotheses, checked through source correspondence and separate elevation measurements.</p></article></div>
<div class="controls"><label>End/adjacent elevation <select id="view"></select></label><label>Original raster threshold <select id="threshold"><option>220</option><option>235</option></select></label><label>Gable candidate <select id="pair"></select></label><label><input id="points" type="checkbox" checked> Source pixels</label><label><input id="fits" type="checkbox" checked> Fitted lines</label></div>
<p id="source-status"></p><div class="panels"><article><h2>Original elevation · slope evidence</h2><svg id="gable" role="img" aria-label="Original elevation with source slope pixels and fitted lines"></svg><p class="small">Blue and orange points are original even-column fit and odd-column check pixels. Dashed lines are fitted hypotheses spanning any recorded source gaps. The red ridge is an inferred line intersection, not an original source vertex. No eave-to-eave depth is independently measured from these fits.</p></article><article><h2>Original long elevation · height evidence</h2><svg id="long" role="img" aria-label="Original long elevation with source ridge and panel eave boundaries"></svg><p class="small">Blue: recovered source ridge grid boundary. Gold: dominant tall-panel lower boundary, above the fascia. The adjacent small gable remains separate; its visible slopes do not establish a complete roof or building association.</p></article></div>
<div class="controls"><label><input id="failures" type="checkbox"> Include disagreeing gable checks</label></div><p id="check-summary"></p><table><thead><tr><th>Source elevation / threshold</th><th>Result</th><th>Ridge difference</th><th>Pitch differences</th><th>Orientation link</th></tr></thead><tbody id="checks"></tbody></table>
<script type="application/json" id="data">PAYLOAD</script><script>
const data=JSON.parse(document.getElementById('data').textContent),ns='http://www.w3.org/2000/svg',model=document.getElementById('model'),view=document.getElementById('view'),threshold=document.getElementById('threshold'),pair=document.getElementById('pair');
function el(tag,attrs,parent){let e=document.createElementNS(ns,tag);for(let [k,v]of Object.entries(attrs))e.setAttribute(k,v);parent.append(e);return e}function line(svg,points,color,cls,dash=false,width=2){let e=el('polyline',{points:points.map(p=>p.join(',')).join(' '),stroke:color,fill:'none','stroke-width':width,class:cls},svg);if(dash)e.setAttribute('stroke-dasharray','5 4');return e}function image(svg,v,box=null){svg.replaceChildren();let b=box||v.display_box;svg.setAttribute('viewBox',`${b[0]} ${b[1]} ${b[2]-b[0]} ${b[3]-b[1]}`);el('image',{href:v.png,width:v.size[0],height:v.size[1]},svg)}function selected(){return data.evidence.models[Number(model.value)]}
for(let i=0;i<data.evidence.models.length;i++){let m=data.evidence.models[i],h=data.evidence.long_profile_reviews.flatMap(p=>p.heights).find(h=>h.id===m.source_height_review_id),o=document.createElement('option');o.value=i;o.textContent='Long source threshold '+h.threshold;model.append(o)}
let order=[...data.evidence.gable_views].sort((a,b)=>{function rank(v){let c=data.evidence.gable_checks.filter(c=>c.view_id===v.view_id&&c.status==='independent_source_gable_heights_and_pitches_agree');return c.some(c=>c.source_gable_orientation_link_supported)?0:c.length?1:v.variants.some(v=>v.lines.length)?2:3}return rank(a)-rank(b)||a.caption.localeCompare(b.caption)});for(let v of order){let o=document.createElement('option');o.value=v.view_id;o.textContent=v.caption;view.append(o)}
function choices(){let m=selected(),v=data.evidence.gable_views.find(v=>v.view_id===view.value);pair.replaceChildren();if(!m||!v)return;let scan=v.variants.find(v=>v.threshold===Number(threshold.value)),checks=data.evidence.gable_checks.filter(c=>c.model_id===m.id&&c.view_id===v.view_id&&c.threshold===scan.threshold);let rows=[...scan.gable_pairs].sort((a,b)=>{let aa=checks.find(c=>c.source_gable_pair_id===a.id)?.status==='independent_source_gable_heights_and_pitches_agree',bb=checks.find(c=>c.source_gable_pair_id===b.id)?.status==='independent_source_gable_heights_and_pitches_agree';return Number(bb)-Number(aa)});if(!rows.length){let o=document.createElement('option');o.value='';o.textContent='No complete pair · retain source slopes';pair.append(o)}for(let i=0;i<rows.length;i++){let o=document.createElement('option'),c=checks.find(c=>c.source_gable_pair_id===rows[i].id);o.value=rows[i].id;o.textContent=`${i+1} of ${rows.length} · ${c?.status==='independent_source_gable_heights_and_pitches_agree'?'agrees':'disagrees'}`;pair.append(o)}draw()}
function draw(){let m=selected();if(!m)return;let mesh=m.mesh,svg=document.getElementById('roof');svg.replaceChildren();let az=Number(document.getElementById('yaw').value)*Math.PI/180,tilt=Number(document.getElementById('tilt').value)*Math.PI/180;function project(p){let x=p[0]*Math.cos(az)-p[1]*Math.sin(az),depth=p[0]*Math.sin(az)+p[1]*Math.cos(az);return [400+x*26,305+depth*Math.sin(tilt)*26-p[2]*Math.cos(tilt)*26]}let tris=mesh.triangles.map((indices,i)=>({indices,i,depth:indices.reduce((s,k)=>s+mesh.vertices[k][0]*Math.sin(az)+mesh.vertices[k][1]*Math.cos(az),0)/3})).sort((a,b)=>a.depth-b.depth);for(let {indices,i}of tris)el('polygon',{points:indices.map(k=>project(mesh.vertices[k]).join(',')).join(' '),fill:i<2?'#7298af':'#a4bfcb',stroke:'#36586d','stroke-width':.6,class:'roof-triangle','data-triangle':i},svg);for(let [a,b]of [[0,1],[1,3],[3,5],[5,4],[4,2],[2,0],[2,3]])line(svg,[project(mesh.vertices[a]),project(mesh.vertices[b])],'#28485f','roof-edge',false,1.3);
let length=mesh.vertices[1][0]-mesh.vertices[0][0],depth=mesh.vertices[4][1]-mesh.vertices[0][1];document.getElementById('measurements').textContent=`Length ${length.toFixed(3)} × depth ${depth.toFixed(3)} nominal m. Eave ${mesh.vertices[0][2].toFixed(3)} m; ridge ${mesh.vertices[2][2].toFixed(3)} m above printed Shop Level. Pitches ${mesh.left_pitch_degrees.toFixed(3)}° / ${mesh.right_pitch_degrees.toFixed(3)}°. Printed state: ${m.source_construction_state}.`;
let counts=data.evidence.counts;document.getElementById('summary').textContent=`${counts.conditional_roof_models} source-height witnesses, ${counts.distinct_roof_meshes} distinct roof geometry. ${counts.gable_checks_agree} of ${counts.gable_checks} retained gable/model comparisons agree. No world blocks, accepted physical components or training labels.`;
let plan=data.evidence.plan_reviews.find(p=>p.id===m.source_plan_review_id),planView=data.views[plan.source_view_id],mat=planView.native_to_pixel_matrix;function pixel(p){return [p[0]*mat[0]+p[1]*mat[2]+mat[4],p[0]*mat[1]+p[1]*mat[3]+mat[5]]}let triple=plan.triples.find(t=>t.id===m.source_plan_triple_id),lines=triple.source_line_ids.map(id=>plan.lines.find(l=>l.id===id)),all=lines.flatMap(l=>l.source_endpoints_pdf_native.map(pixel)),xs=all.map(p=>p[0]),ys=all.map(p=>p[1]),box=[Math.max(0,Math.min(...xs)-40),Math.max(0,Math.min(...ys)-40),Math.min(planView.size[0],Math.max(...xs)+40),Math.min(planView.size[1],Math.max(...ys)+40)];let ps=document.getElementById('plan');image(ps,planView,box);for(let i=0;i<lines.length;i++)line(ps,lines[i].source_endpoints_pdf_native.map(pixel),i===1?'#bd8300':'#2368b2','native-plan-line',false,2);
let g=data.profiles[m.source_profile_id],h=data.evidence.long_profile_reviews.flatMap(p=>p.heights).find(h=>h.id===m.source_height_review_id),variant=g.variants.find(v=>v.threshold===h.threshold),long=document.getElementById('long');image(long,data.views[m.source_long_view_id]);let span=variant.source_upper_span_pixels;line(long,[[span[0],h.source_ridge_grid_y],[span[1],h.source_ridge_grid_y]],'#2368b2','source-ridge-height',false,2);line(long,[[span[0],h.source_eave_grid_y],[span[1],h.source_eave_grid_y]],'#bd8300','source-eave-height',false,2);
let source=data.evidence.gable_views.find(v=>v.view_id===view.value),scan=source.variants.find(v=>v.threshold===Number(threshold.value)),p=scan.gable_pairs.find(p=>p.id===pair.value),gs=document.getElementById('gable');let sourceBox=[...data.views[source.view_id].display_box];if(scan.lines.length){let sourceY=scan.lines.flatMap(l=>l.source_pixels.map(p=>p.y));sourceBox=[0,Math.max(0,Math.min(...sourceY)-50),data.views[source.view_id].size[0],data.views[source.view_id].size[1]];if(source.view_id===m.source_long_view_id)sourceBox[1]=Math.min(sourceBox[1],Math.max(0,h.source_ridge_grid_y-30))}image(gs,data.views[source.view_id],sourceBox);let sl=p?[scan.lines.find(l=>l.id===p.left_line_id),scan.lines.find(l=>l.id===p.right_line_id)]:scan.lines;for(let l of sl){if(document.getElementById('points').checked)for(let q of l.source_pixels)el('circle',{cx:q.x,cy:q.y,r:.9,fill:q.role==='fit'?'#2368b2':'#cf8400',class:'source-pixel '+q.role},gs);if(document.getElementById('fits').checked)line(gs,l.source_x_interval.map(x=>[x,l.slope*x+l.intercept]),'#963c6c','fitted-source-line',true,1)}if(p)el('circle',{cx:p.inferred_ridge_pixel[0],cy:p.inferred_ridge_pixel[1],r:3,fill:'#bc3048',class:'inferred-ridge'},gs);
let selectedCheck=p?data.evidence.gable_checks.find(c=>c.model_id===m.id&&c.view_id===source.view_id&&c.threshold===scan.threshold&&c.source_gable_pair_id===p.id):null;document.getElementById('source-status').textContent=p?`Selected source pair: ridge ${p.nominal_ridge_height_m.toFixed(3)} nominal m; pitches ${p.left_pitch_degrees.toFixed(3)}° / ${p.right_pitch_degrees.toFixed(3)}°. ${selectedCheck.status==='independent_source_gable_heights_and_pitches_agree'?'Agrees with fixed model.':'Disagrees with fixed model.'} Orientation link ${selectedCheck.source_gable_orientation_link_supported?'supported as a source hypothesis':'held; dimensional check only'}. The model is not refitted.`:`${scan.lines.length} original slope candidates; no complete gable pair. Missing sides, eaves and building association remain unresolved.`;
let checks=data.evidence.gable_checks.filter(c=>c.model_id===m.id),agree=checks.filter(c=>c.status==='independent_source_gable_heights_and_pitches_agree');document.getElementById('check-summary').textContent=`${agree.length} of ${checks.length} checks agree for this source-height witness. All alternative source pairs are retained; no physical correspondence is accepted.`;let table=document.getElementById('checks');table.replaceChildren();for(let c of checks){let ok=c.status==='independent_source_gable_heights_and_pitches_agree';if(!ok&&!document.getElementById('failures').checked)continue;let tr=document.createElement('tr');if(ok)tr.className='agree';for(let value of [data.views[c.view_id].caption+' / '+c.threshold,ok?'Agrees':'Disagrees',c.ridge_difference_nominal_m.toFixed(4)+' nominal m',c.pitch_differences_degrees.map(v=>v.toFixed(3)+'°').join(' / '),c.source_gable_orientation_link_supported?'Source hypothesis supported':'Held / dimensional check only']){let td=document.createElement('td');td.textContent=value;tr.append(td)}table.append(tr)}}
function objText(){let m=selected();return ['# Conditional unplaced roof hypothesis','# Source review SHA256 '+data.review_sha256,'# Nominal metres; x longitudinal, y transverse, z above printed Shop Level','# Continuous roof planes assumed; no physical identity or placement acceptance','o conditional_roof',...m.mesh.vertices.map(p=>'v '+p.join(' ')),...m.mesh.triangles.map(t=>'f '+t.map(i=>i+1).join(' '))].join('\n')+'\n'}
document.getElementById('obj').addEventListener('click',()=>{let url=URL.createObjectURL(new Blob([objText()],{type:'text/plain'})),a=document.createElement('a');a.href=url;a.download='conditional-roof.obj';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});model.addEventListener('change',choices);view.addEventListener('change',choices);threshold.addEventListener('change',choices);pair.addEventListener('change',draw);for(let id of ['points','fits','failures'])document.getElementById(id).addEventListener('change',draw);for(let id of ['yaw','tilt'])document.getElementById(id).addEventListener('input',draw);choices();
</script></html>'''.replace('PAYLOAD',json.dumps(payload,separators=(',',':')).replace('<','\\u003c'))
    if len(html.encode())>64000000:raise ValueError('Gable roof review HTML budget exceeded')
    output.parent.mkdir(parents=True,exist_ok=True);output.write_text(html)
    return {'output':str(output),'source_images':len(payload['views']),'models':len(evidence['models']),'bytes':output.stat().st_size}

if __name__=='__main__':
    p=argparse.ArgumentParser(description=__doc__)
    for k in ('gable','profile','preview','components','views','output'):p.add_argument('--'+k,type=Path,required=True)
    a=p.parse_args();print(json.dumps(render(a.gable,a.profile,a.preview,a.components,a.views,a.output)))
